        var medio = x.sugerencia
          ? '<span style="' + EST.flecha + '">&rarr;</span>' +
            '<button type="button" data-i="' + i + '" data-accion="usar" style="' + EST.usar + '">' +
            x.sugerencia + '</button>'
          : '<span style="' + EST.motivo + '">' + x.motivo + '</span>';
